Method.Implementation:
		#dim status AS %Status=$$$OK
		$$$TRACE(" Inside CallPatientServices()..........")
		set mrnPar=""
      $$$TRACE(" Operation Type: " _ opType) 
     $$$TRACE(" Target Operation: " _ process1.PatientServiceTargetConfigName) 
     set httpPingServiceRequestObj=##class(IHC.ITF.ITFCOMMON.Request.HiePatientService).%New() 
     set httpPingServiceRequestObj.accessToken = token
     set httpPingServiceRequestObj.operationType = opType  
     set httpPingServiceRequestObj.identifier = mrn 
     set httpPingServiceRequestObj.streamObject = jsonReq
     $$$TRACE(" Calling Patient Service "_opType_" - BEGIN ")     
     set status = process1.SendRequestSync(process1.PatientServiceTargetConfigName,httpPingServiceRequestObj,.patientServiceResponse)
     $$$TRACE(" Calling Patient Service "_opType_" - END ")
     if (status=$$$OK){
	    $$$TRACE("Call PatientService "_opType_" Operation OK status.")      
        set patServiceResponseData=patientServiceResponse.Stream  
        set statusCode = patientServiceResponse.Attributes.GetAt("StatusCode")       
        set stream =   patServiceResponseData
       	set respData = ""
       	While 'stream.AtEnd { 
       		set respData = respData _ stream.ReadLine(,.sc,.eol)       		
       	}
        $$$TRACE(" httpStatusCode: "_statusCode)    

       // set respdata = respData _ " JSON Request: "_jsonProcessRequest.StringValue_$CHAR(10)

        if (statusCode'="200"){
	    	if (statusCode="401"){
		   		$$$TRACE("  CheckError... ")
		   		set status=##class(IHC.ITF.ITFCOMMON.Utility).RetryCheckError(process1.%ConfigName,"Http Status code: ["_statusCode_"]. Invalid access token. Response: ["_respData_"]. Retrying...") 
		   	}elseif (statusCode="400"){
		    	$$$TRACE("  In Status Code 400... ")
		    	$$$TRACE(" respData "_respData)
		    	set status=##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(process1.%ConfigName,"Http Status code: ["_statusCode_"]. Invalid/Bad request.   Response: "_respData)
   		    }elseif (statusCode [ "5"){
			    $$$TRACE("  HTTP status codes starting 5.. ")
		   		set status=##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(process1.%ConfigName,"Http Status code: ["_statusCode_"]. Response: ["_respData_"].") 
		    }else{
		    	$$$TRACE("  DisableMsgError.... ")
        		set status=##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(process1.%ConfigName," Response from Patient Service Post Operation: "_respData) 
		    }
		} else {
        		$$$TRACE("PatientService call status 200 OK !!! ")
        		Do ##class(IHC.ITF.ITFCOMMON.Utility).ResetError(process1.%ConfigName) 

        		set respJSONstring = respData          		
          		$$$TRACE(" respData "_respData)
          		set consumedJSONobj = ##class(%DynamicAbstractObject).%FromJSON(respJSONstring)          		
          		set iterator =  consumedJSONobj.%GetIterator()
                 while iterator.%GetNext(.key,.value) { 
                 	$$$TRACE(" Key: "_key_" Value: "_value)
                 	if (key="status"){
	                 	 if (value="SUCCESS"){
		                 	$$$TRACE(" Status: "_value)		                 	
		                 	set primaryIdsArr = ((consumedJSONobj.%Get("data")).%Get("primaryIds"))  
    					    $$$TRACE("  primaryIdsArr Size: "_primaryIdsArr.%Size())  		    					    
    		 				// Loop through a JSON Array
  							Set arrObj = primaryIdsArr.%GetIterator()
  			  				while arrObj.%GetNext(.key, .value) {	  			
	  						  Set arrElemObj = value.%GetIterator()		  						  
	  			  			  while arrElemObj.%GetNext(.key, .value) {
		  			  			$$$TRACE("  key: "_key_" Value: "_value)
								if (value = "INMT"){
									if (arrElemObj.%GetNext(.key, .value)){
										$$$TRACE("  key2: "_key_" Value2: "_value)
										set mrnPar = value										
									}		  			  				
		  			  			}
	  			  			  }
  							}             	   
	                 	 }else{
		                 	 $$$TRACE(" Status: "_value)
		                 	 set context.errResp = "1"
		                 	 $$$TRACE(" respJSONstring (ERRTXT): "_respJSONstring)	
		                 	 set inputDataErrCodeList = $LISTFROMSTRING(context.inputDataErrorCodes, ",")
	   						 Set lenInDataErrCodeList = $ListLength(inputDataErrCodeList)
	   						 $$$TRACE("  lenInDataErrCodeList : "_lenInDataErrCodeList)
	   						 For i=1:1:lenInDataErrCodeList {
		   						 set listItem = $List(inputDataErrCodeList,i)
								Set isInDataErrCodeFound = respJSONstring[ listItem	
								$$$TRACE("  isInDataErrCodeFound:"_isInDataErrCodeFound_" ErrCode:"_listItem)
								if (isInDataErrCodeFound=1) quit				
							 }
							 if (isInDataErrCodeFound=1) {
		    					$$$TRACE(" InputDataError.. errorText: "_respJSONstring)
	        					set status=##class(IHC.ITF.ITFCOMMON.Utility).InputDataError(process1.%ConfigName," Skipping the record... Response from Patient Service Post Operation: "_respJSONstring)
							 }else{
								 set retryErrCodeList = $LISTFROMSTRING(context.retrySameDisableErrorCodes, ",")
								 Set lenRetryErrCodeList = $ListLength(retryErrCodeList)
	   							 $$$TRACE("  lenRetryErrCodeList : "_lenRetryErrCodeList)
	   							 For i=1:1:lenRetryErrCodeList {
		   	 						set listItem = $List(retryErrCodeList,i)
									Set isRetryErrCodeFound = respJSONstring[ listItem	
									$$$TRACE("  isRetryErrCodeFound:"_isRetryErrCodeFound_" ErrCode:"_listItem)
									if (isRetryErrCodeFound=1) quit				
								 }
	    						if (isRetryErrCodeFound=1) {
								    $$$TRACE(" RetryCheckError.. errorText "_respJSONstring)
	        						Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryCheckError(process1.%ConfigName,"TimedOut. No Successful Response from Patient service: ["_respJSONstring_"]. Retrying ..")
								}else{
								 if respJSONstring [ "line 1 limit is 30"{
			                 		 set status=##class(IHC.ITF.ITFCOMMON.Utility).InputDataError(process1.%ConfigName," Length of the Address1 from IDX(NV) Adt in PID-11.1 is more than 30. Response from Patient Service Post Operation: "_respJSONstring)	                
			                 	 }else{
								 	$$$TRACE(" Unknown/Unhandled Error. Response from the Hie Patient Service: errorText: "_respJSONstring)
	    						 	set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(process1.%ConfigName," Unknown/Unhandled error: "_respJSONstring) 
			                 	 }
								}
							 }              	
		                 }
	                }

                }                 
        } 
    }else{
	    set errTxt = $SYSTEM.Status.GetOneErrorText(status)
	    $$$TRACE("Call PatientService ERR TEXT: "_errTxt)
	    set retryErrCodeList = $LISTFROMSTRING(context.retrySameDisableErrorCodes, ",")
	   	Set lenRetryErrCodeList = $ListLength(retryErrCodeList)
	   	$$$TRACE("  lenRetryErrCodeList : "_lenRetryErrCodeList)
	   	For i=1:1:lenRetryErrCodeList {
		   	 set listItem = $List(retryErrCodeList,i)
			Set isRetryErrCodeFound = errTxt[ listItem	
			$$$TRACE("  isRetryErrCodeFound:"_isRetryErrCodeFound_" ErrCode:"_listItem)
			if (isRetryErrCodeFound=1) quit				
		}

	    if (isRetryErrCodeFound=1) {
		    $$$TRACE(" RetryCheckError.. errorText "_errTxt)
	        Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryCheckError(process1.%ConfigName,"TimedOut. No Successful Response from Patient service: ["_errTxt_"]. Retrying ..")
		}else{
			$$$TRACE("Call PatientService ERR TEXT: "_errTxt)
	    	set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(process1.%ConfigName," Unknown/Unhandled error: "_errTxt) 
		}    	   
    } 

	 //set mrnPar = mrnFromResp      
     quit status
